// Generated by scripts/build-lesson-bundles.cjs.
((globalThis, register) => {
'use strict';
globalThis.KENGURU_CHOICE_LAYOUTS = {};
'use strict';

globalThis.makeMedvezhonokEdition = function (year, grade, rows, material = {}) {
  const letters = 'АБВГД';
  const plain = value => value.replace(/<\/?(?:em|strong|u)>/g, '');
  const escape = value => value.replaceAll('&', '&amp;').replaceAll('<', '&lt;').replaceAll('>', '&gt;');
  const grades = grade.split('-').map(Number);
  const lessons = rows.map(({author, question, choices, key, review, figure, unrated, points, acceptedAnswers}, index) => {
    const [title, idea, check] = review;
    const answer = letters.indexOf(key);
    if (acceptedAnswers && (!acceptedAnswers.includes(answer) || new Set(acceptedAnswers).size !== acceptedAnswers.length ||
        !acceptedAnswers.every(index => Number.isInteger(index) && index >= 0 && index < choices.length))) {
      throw new Error('Invalid accepted answers in ' + year + '/' + grade + '/' + (index + 1));
    }
    const textChoices = choices.map(plain);
    const options = figure?.options?.map(({src, detailSrc, description, pixelWidth, pixelHeight}, i) => ({
      image: src, ...(detailSrc ? {detailSrc} : {}), description, pixelWidth, pixelHeight, text: figure.onlyPictures ? '' : textChoices[i],
    })) ?? textChoices.map(text => ({text}));
    return {
      number: index + 1, title, author, question: plain(question), choices: textChoices,
      ...(plain(question) !== question ? {formattedQuestion: question} : {}),
      ...(textChoices.some((value,i) => value !== choices[i]) ? {formattedChoices: choices} : {}),
      ...(acceptedAnswers ? {acceptedAnswers} : {}),
      ...(unrated ? {questionNote: unrated, archiveAnswer: key} : {}),
      ...(figure ? {
        choiceLayout: {options, condition: figure.condition},
        choiceImages: options.map(option => option.image),
        ...(figure.condition ? {conditionImage: figure.condition.src, conditionAlt: figure.condition.alt} : {}),
      } : {}),
      answer: unrated ? null : answer, points: points ?? (index < 10 ? 3 : index < 20 ? 4 : 5),
      skill: 'Русский медвежонок · Языкознание', hideIntroText: true, showCompletedStep: true,
      steps: [
        ['Выбор', 'Условие задачи', ''],
        ['Первый шаг', 'Рассуждение', idea],
        ['Проверка', 'Проверка', check],
        ['Ответ', unrated ? 'Ответ в архивном ключе' : 'Ответ', ''],
      ],
    };
  });
  const scenes = rows.map(({review, key}, i) => {
    const terms = review.slice(1).map(step => [...new Set(
      Array.from(step.matchAll(/«([^«»\n]{1,44})»/gu), match => match[1])
    )].slice(0, 5));
    return (step, frame) => {
      if (!step) return '';
      const tokens = step === 3 ? (lessons[i].acceptedAnswers ?? [letters.indexOf(key)]).map(index => {
        const result = lessons[i].choices[index].replace(/^\[(.*)\][.]?$/, '$1');
        return letters[index] + (result ? ' · ' + result : '');
      }) : terms[step-1];
      if (step < 3 && tokens.length < 2) return '';
      return '<div class="word-scene" data-result="' + (step === 3) + '">' + tokens.map((token, index) => {
        const reveal = Math.min(1, Math.max(0, (frame - index * 0.65) / 0.42));
        return '<span class="word-token" style="--reveal:' + reveal.toFixed(3) + '">' + escape(token) + '</span>';
      }).join('') + '</div>';
    };
  });
  const reviewedKey = rows.some(row => row.reviewedEdition);
  return {
    id: year + '-medvezhonok-' + grade, year, grades, subject: 'ru',
    label: grades.join('–') + (grades.length === 1 ? ' класс' : ' классы'),
    sources: {
      contest: 'Русский медвежонок',
      tasksUrl: 'assets/medvezhonok/' + year + '/' + (material.tasksFile ?? grade + '.pdf'),
      reviewedKey,
      answersUrl: 'assets/medvezhonok/' + year + '/' + (reviewedKey ? 'reviewed-' + grade + '.pdf' : material.answersFile ?? grade + '-answers.pdf'),
      ...(material.solutionsFile ? {solutionUrl: 'assets/medvezhonok/' + year + '/' + material.solutionsFile} : {}),
      ...(year === 2004 && grade === '2-3' ? {solutionUrl: 'assets/medvezhonok/2004/2-3-answers.pdf'} : {}),
    },
    lessons, scenes,
  };
};

register(globalThis.makeMedvezhonokEdition(2025, "10-11", [{"author":"О. Подлесская","question":"<em>В XXI веке столица переживает строительный _____.</em>","choices":["бах","бабах","бум","бряк","бац."],"key":"В","review":["Строительство в столице","Здесь нужно назвать резкий подъём строительства. «Бах», «бабах», «бряк» и «бац» обычно передают отдельный звук или удар.","Быстрый рост или оживление называют бумом. Устойчивое сочетание — «строительный бум»."]},{"author":"А. Остроумова","question":"В каком примере пропущена не та буква, что в остальных?","choices":["в_йти в раж","в_йти во вкус","в_йти в эфир","в_йти в дом","в_йти в положение."],"key":"В","review":["«Войти» и «выйти»","Слова «в раж», «во вкус», «в дом» и «в положение» сочетаются с «войти». В каждом случае пропущена О.","О начале передачи говорят «выйти в эфир». Только здесь пропущена Ы."]},{"author":"П. Аркадьев","question":"Какое из данных выражений встречается реже других?","choices":["моя жена","моя невестка","моя вдова","моя тёща","моя свекровь."],"key":"В","review":["Кто говорит о родственнице","Обрати внимание, кто может произнести сочетание со словом «моя». Жена, невестка, тёща и свекровь — обозначения, которые человек обычно употребляет при жизни.","Вдовой женщина становится после смерти мужа. Слова «моя вдова» от его лица возможны разве что при разговоре о будущем, поэтому это самое редкое сочетание."]},{"author":"А. Пиперски","question":"Данные ниже глаголы в современном русском языке не употребляются без -ся. Но если добавить приставку по-, то в одном из глаголов -ся можно будет убрать. В каком?","choices":["нравиться","бороться","смеяться","улыбаться","бояться."],"key":"Б","review":["Приставка и «-ся»","Добавим «по-» к глаголам и проверим, сохраняется ли слово без «-ся». «Понравить», «посмеять», «поулыбать» и «побоять» в таком употреблении не подходят.","От «бороться» получается «побороться», а рядом с ним есть «побороть»: «побороть страх». Поэтому ключевой глагол — «бороться»."]},{"author":"А. Пиперски","question":"В какой фразе с наибольшей вероятностью будет опущено слово <em>минут</em>?","choices":["Антон вбежал на перрон без трёх минут пять.","Собрание началось в десять минут шестого.","Футболисты закончили матч в двадцать пять минут шестого.","Вася обещал прийти без пяти минут шесть.","В Москве шесть часов пятнадцать минут."],"key":"Г","review":["Где опускают «минут»","Во фразе с «без» уже понятно, что речь о времени до очередного часа. Такая конструкция особенно привычна с округлённым числом минут.","«Вася обещал прийти без пяти шесть» — естественное сокращение. «Без трёх минут пять» называют точнее, и слово «минут» здесь обычно сохраняют."]},{"author":"П. Аркадьев","question":"Петя прочитал в интернете: <em>В сам музей не пошли, предпочёв погулять по городку,</em> — и подумал, что деепричастие <em>предпочёв</em> образовано неправильно. А какую форму было бы правильнее всего использовать в таком предложении?","choices":["предпочитая","предпочтя","предпочтив","предпочтёв","Петя неправ, это правильная форма."],"key":"Б","review":["Деепричастие от «предпочесть»","Герои уже сделали выбор, поэтому нужна форма совершенного вида от «предпочесть». «Предпочитая» относится к несовершенному «предпочитать».","Сравни «прочесть — прочтя» и «счесть — сочтя». Точно так же от «предпочесть» образуется «предпочтя»."]},{"author":"И. Рубанов","question":"Пуганая ворона _____ боится.","choices":["кита","кота","крота","куста","моста."],"key":"Г","review":["Пуганая ворона","В пословице страх распространяется даже на предмет, который вороне не угрожает. Птица может принять шевеление веток за опасность.","Устойчивое выражение звучит так: «Пуганая ворона куста боится». Из пяти вариантов восстанавливаем «куста»."]},{"author":"А. Сомин","question":"В английском языке один из математических символов иногда называют __________.","choices":["смелой пятёркой","глупой шестёркой","хитрой семёркой","ленивой восьмёркой","злой девяткой."],"key":"Г","review":["Прозвище символа","Вспомни знак бесконечности ∞. По форме это восьмёрка, повернутая набок.","В английском шутливом названии восьмёрка как будто лежит вместо того, чтобы стоять. Поэтому её называют «ленивой восьмёркой»."]},{"author":"С. Дьяченко","question":"В некоторых русских говорах есть наречие состани (встречается также вариант на один звук длиннее). Что означает это наречие?","choices":["‘рано утром’","‘поздно вечером’","‘перед ужином’","‘после обеда’","‘перед грозой’."],"key":"А","review":["Диалектное наречие","У второй формы этого слова — «совстани» — слышится связь с тем, как человек встаёт. Речь о начале дня.","У Даля обе формы обозначают время с раннего утра. Из ответов подходит «рано утром»."]},{"author":"А. Сомин","question":"Образуем фамилии от приведённых ниже имён. В четырёх случаях они полностью совпадут с формой родительного падежа множественного числа соответствующего имени, но в одном случае ударение в фамилии может отличаться от ударения в этой форме имени. От какого имени образуется эта фамилия?","choices":["Антон","Дмитрий","Иван","Пётр","Фёдор."],"key":"В","review":["Ударение в фамилии","Сравни названия групп: несколько Анто́нов, Дми́триев, Ива́нов, Петро́в, Фёдоров. Теперь произнеси те же написания как фамилии.","Фамилия бывает Ивано́в, с ударением на последнем слоге. У формы родительного множественного числа от «Иван» ударение остаётся на А: «Ива́нов»."]},{"author":"А. Сомин","question":"Перед вами цитата из статьи, опубликованной в газете «Ленинградская правда» в 1967 году: <em>Раньше это (увлечение чем-либо) называлось _____, теперь именуется хобби.</em> Какое слово пропущено на месте прочерка?","choices":["санками","лыжей","коньком","роликом","самокатом."],"key":"В","review":["Увлечение в старой газете","Слово в пропуске должно обозначать увлечение, хотя все пять вариантов называют спортивные вещи.","«Мой конёк» говорят о любимом занятии или теме, в которой человек хорошо разбирается. В цитате было «называлось коньком»."]},{"author":"Л. Фёдорова","question":"Какое слово отличается от остальных по грамматическим признакам?","choices":["школьница","кружевница","возница","озорница","ровесница."],"key":"В","review":["Род слова","Школьница, кружевница, озорница и ровесница обозначают женщин или девочек. С ними согласуются «моя» и «новая».","«Возница» — тот, кто правит лошадьми в повозке. У слова мужской род: «умелый возница», «этот возница»."]},{"author":"А. Манусов и Ф. Тучак","question":"Один школьник ошибочно предположил, что определённый глагол, обозначающий особенности произношения гласных в некоторых регионах России, образован от названия реки. Какая это река?","choices":["Ангара","Волга","Енисей","Лена","Ока."],"key":"Д","review":["Название реки и произношение","В некоторых говорах безударный О произносят отчётливо и различают безударные О и А. Это называют «окать».","В слове «окать» слышится название реки Ока. Сам глагол образован от названия звука О."]},{"author":"О. Подлесская","question":"В каком примере выделенное выражение сильно отличается по смыслу от других четырёх?","choices":["Да... <strong>В десять лет</strong> другим человеком стал. А какая причина? Заработался… (А. П. Чехов)","Кто черни светской не чуждался, Кто <strong>в двадцать лет</strong> был франт иль хват… (А. С. Пушкин)","Нельзя же тебе одной ехать, душечка. <strong>В семнадцать лет</strong>! (А. П. Чехов)","<strong>В восемнадцать лет</strong> Оленин был так свободен, как только бывали свободны русские богатые молодые люди сороковых годов, с молодых лет оставшиеся без родителей. (Л. Н. Толстой)","Я вспомнил, что я ровно ничего не умею делать и <strong>в шестнадцать лет</strong> еду к матери не для облегчения её участи, а скорее для усиления её забот. (Н. С. Лесков)"],"key":"А","review":["Возраст или срок","В примерах о франте, поездке, Оленине и возвращении к матери выражение отвечает на вопрос «в каком возрасте?».","Герой Чехова говорит о том, сколько времени потребовалось, чтобы он стал другим. В его реплике «в десять лет» значит «за десять лет»."]},{"author":"Л. Фёдорова","question":"<em>Высокой страсти не имея\nДля звуков жизни не щадить,\nНе мог он ямба от хорея,\nКак мы ни бились, отличить.</em>\nРазбираясь с этим фрагментом «Евгения Онегина» А. С. Пушкина, в первых двух строках Оля установила такие синтаксические связи: 1) не имея чего? страсти; 2) страсти какой? высокой; 3) не имея для чего? для звуков; 4) для звуков чего? жизни. Коля сказал, что не все связи установлены верно. Какие не верны?","choices":["1-я","только 3-я","3-я и 4-я","только 4-я","Коля ошибся, все связи установлены верно."],"key":"В","review":["Порядок слов у Пушкина","Читай первые две строки вместе. «Не имея высокой страсти» содержит связи «не имея чего?» — «страсти» и «страсти какой?» — «высокой».","Переставим остальные слова: «не щадить жизни для звуков». И «жизни», и «для звуков» зависят от «не щадить». Связи 3 и 4 установлены неверно."]},{"author":"С. Сай","question":"Даны слова: виноград, соль, табак, чеснок. Поставьте им в соответствие слова из предлагаемого списка и найдите слово, для которого не находится пары.","choices":["щепотка","головка","кисть","ладонь","понюшка."],"key":"Г","review":["Меры и порции","Проверь, как обычно называют количество каждого продукта: «кисть винограда», «щепотка соли», «головка чеснока».","Ещё есть «понюшка табака», то есть порция для одного вдыхания. Слово «ладонь» осталось без пары."]},{"author":"А. Пиперски","question":"Расставьте названия частей тела в том же порядке, в каком они упоминаются в слове оториноларинголог.","choices":["ухо, горло, нос","горло, нос, ухо","нос, ухо, горло","нос, горло, ухо","ухо, нос, горло."],"key":"Д","review":["Слово из трёх частей","Разделим слово на части «ото-», «рино-» и «ларинго-». «Ото-» относится к уху, «рино-» — к носу, «ларинго-» — к гортани.","По порядку получается «ухо, нос, горло». Последняя часть «-лог» обозначает специалиста."]},{"author":"И. Иткин","question":"Знаменитый лингвист Андрей Анатольевич Зализняк в одной из своих работ приводит несколько итальянских слов (c читается как к): stradali ‘дорожные’, costi ‘цены’, porca ‘свинья’, perina ‘маленькая груша’. Какое ещё итальянское слово приводит Зализняк в той же работе?","choices":["volare ‘лететь’","latte ‘молоко’","affilata ‘острая’","inverno ‘зима’","gusto ‘вкус’."],"key":"Д","review":["Итальянские созвучия","Прочитай «stradali», «costi», «porca», «perina» так, как подсказано. Получатся знакомые русские формы «страдали», «кости», «порка», «перина».","Среди вариантов тот же эффект даёт «gusto». Оно звучит как русское «густо», хотя по-итальянски означает «вкус»."]},{"author":"С. Сай","question":"Попробуйте перевести с литовского языка предложение <em>popiet lis</em> (литовский язык относится к балтийской группе индоевропейской семьи).","choices":["В роще запоёт иволга.","На дорогу выбежала лиса.","К вечеру вода нагрелась.","Осенью речка замёрзла.","После обеда пойдёт дождь."],"key":"Д","review":["Фраза по-литовски","В «popiet» начальная часть «po-» близка к «после», а «pietūs» по-литовски обозначает обед. Поэтому «popiet» указывает на время после обеда.","Глагол «lis» — форма будущего времени со значением «пойдёт дождь». Целиком фраза означает «После обеда пойдёт дождь»."]},{"author":"А. Леонтьева","question":"Какая буква <strong>не</strong> может быть пропущена в сочетании слов <em>пробуд_т это ощущение</em>, если известно, что оно соответствует нормам русского литературного языка?","choices":["е","и","я","у","любая из этих букв может быть пропущена."],"key":"Г","review":["Формы с основой «пробуд-»","«Пробудит это ощущение» и «пробудят это ощущение» содержат формы глагола «пробудить». «Это ощущение пробудет со мной» содержит форму другого глагола, «пробыть».","«Пробудут» означало бы, что кто-то или что-то во множественном числе проведёт некоторое время. «Это ощущение» единственного числа и не обозначает срок. Поэтому буква У не подходит."]},{"author":"Е. Муравенко","question":"Вставьте гласные е или и вместо пропусков: 1) д_р_вяшка, 2) д_р_жёр, 3) д_р_ктива. В каких двух словах первые четыре буквы совпадают?","choices":["в 1-м и 2-м","в 1-м и 3-м","во 2-м и 3-м","во всех совпадают","во всех разные."],"key":"Д","review":["Две безударные гласные","Восстанови написания: «деревяшка», «дирижёр», «директива». Сравни первые четыре буквы, не учитывая продолжения слов.","Получаем три разные последовательности: ДЕРЕ, ДИРИ и ДИРЕ. Совпадающей пары нет."]},{"author":"А. Сомин","question":"Перед вами цитата из романа А. С. Пушкина «Евгений Онегин»:\n<em>Любви все возрасты покорны;\nНо юным, девственным сердцам\nЕё порывы благотворны,\nКак бури <strong>вешние</strong> полям.</em>\nКакую характеристику бурь описывает слово <em>вешние</em>?","choices":["силу","продолжительность","период возникновения","направление с юга на север","положительное отношение к ним автора."],"key":"В","review":["Значение слова «вешние»","«Вешний» — старое слово, которое сохранилось, например, в сочетании «вешние воды». Так называют воды во время весеннего половодья.","«Вешние бури» — весенние бури. Слово указывает, когда они возникают."]},{"author":"Б. Иомдин","question":"<em>Должна приличная _____\nУметь держать себя в руках.</em>\nКакое слово пропущено в этом шуточном стихотворении?","choices":["девица","синица","волчица","царица","жар-птица."],"key":"Б","review":["Кто держит себя в руках","«Держать себя в руках» обычно значит сохранять самообладание. В шуточных строках часть выражения можно понять буквально.","Вспомни пословицу «Лучше синица в руках, чем журавль в небе». Синица одновременно подходит по грамматике и создаёт игру с буквальным смыслом."]},{"author":"А. Сомин","question":"В дагестанских языках много пространственных падежей. Например, падеж инэссив обозначает нахождение внутри чего-то (‘в доме’), адэлатив — движение от чего-то (‘от дома’), субэлатив — движение из-под чего-то (‘из-под дома’), а контэссив — нахождение вплотную к чему-то (‘вплотную к дому’). А что обозначают падежи суперэлатив, постэссив и инэлатив (на примере слова со значением ‘дом’)?","choices":["на доме; возле дома; с дома","на дом; за домом; в дом","над домом; под домом; сквозь дом","сквозь дом; из-за дома; на доме","с дома; за домом; из дома."],"key":"Д","review":["Откуда и где","В примерах «адэлатив» и «субэлатив» обозначают движение от ориентира. Часть «эссив» в «инэссиве» и «контэссиве» указывает на местоположение.","«Супер-» значит «сверху», «пост-» — «позади», «ин-» — «внутри». Поэтому суперэлатив означает «с дома», постэссив — «за домом», инэлатив — «из дома»."]},{"author":"И. Иткин","question":"Название какой реки пропущено в строке из песни Александра Башлачёва «Подвиг разведчика»?\n<em>Пройду, как рысь, от Альп и до _____.</em>","choices":["Дуная","Евфрата","Онеги","Гаронны","Великой."],"key":"В","review":["Река в песне Башлачёва","В записи «Подвига разведчика» строка с названием реки рифмуется через строку со словом «телеги». Проверь окончания названий.","Форма «Онеги» даёт эту рифму и совпадает с названием, которое поёт Башлачёв. Подходит река Онега."]},{"author":"А. Пиперски","question":"На четыре килограмма, с неугодными, восвояси, от болезни. Какая приставка лишняя?","choices":["за-","о-","от-","по-","рас-."],"key":"А","review":["Приставки и «правиться»","Восстанови глаголы к первым двум фрагментам: «поправиться на четыре килограмма» и «расправиться с неугодными». Использованы «по-» и «рас-».","Дальше получаются «отправиться восвояси» и «оправиться от болезни», с «от-» и «о-». Приставка «за-» осталась лишней."]},{"author":"П. Долгополов","question":"По-польски <em>вождь</em> будет <em>wódz</em>, а <em>ночь</em> — <em>noc</em>. А какой знак препинания называется по-польски <em>cudzysłów</em>?","choices":["многоточие","кавычки","скобки","тире","запятая."],"key":"Б","review":["Польский знак препинания","Сопоставь звучание «cudzysłów» с русским сочетанием «чужое слово». В польском «cudzy» означает «чужой», а «słów» — форма слова «слово».","Цитируя чужие слова, мы заключаем их в кавычки. Так и устроено польское название кавычек."]},{"author":"Б. Иомдин","question":"Один пользователь интернета опубликовал ребус. Другой пользователь решил, что загадано странное слово передрянь, и удивился. Название чего было загадано на самом деле?","choices":["города","страны","реки","животного","растения."],"key":"А","review":["Как прочитать ребус","Разложи «передрянь» на слова и буквы: «перед РЯ — НЬ». Так можно описать, где стоят две части записи.","То же расположение читается в обратном порядке: «РЯ за НЬ». Сложим части как в ребусе и получим «Рязань», название города."]},{"author":"А. Пиперски","question":"Даны названия итальянских футбольных команд с их прозвищами, а также футболки этих команд. Какое прозвище носит команда «Виченца»?","choices":["джалладзурри","бьянкоросси","джаллонери","россадзурри","адзурробьянки."],"key":"Б","review":["Цвета футбольных команд","На футболке «Ромы» есть жёлтый и красный. На футболке «Ювентуса» есть белый и чёрный. Сопоставь цвета с частями их прозвищ.","У «Виченцы» есть белые и красные полосы. Белый даёт «бьянко-» из «бьянконери», красный — «-росси» из «джаллоросси». Получается «бьянкоросси»."],"figure":{"condition":{"src":"assets/medvezhonok/2025/10-11-29.webp","width":983,"height":271,"pixelWidth":983,"pixelHeight":271,"alt":"Четыре футбольные футболки по порядку: «Рома» — красная с жёлтой отделкой, «Интер» — в чёрно-синюю полоску, «Ювентус» — в бело-чёрную полоску, «Виченца» — в бело-красную полоску.","items":[{"src":"assets/medvezhonok/2025/10-11-29-1.webp","width":271,"height":271,"pixelWidth":271,"pixelHeight":271,"alt":"Красная футболка с жёлтой отделкой","caption":"«Рома» · джаллоросси"},{"src":"assets/medvezhonok/2025/10-11-29-2.webp","width":212,"height":271,"pixelWidth":212,"pixelHeight":271,"alt":"Футболка в сине-чёрную полоску","caption":"«Интер» · нерадзурри"},{"src":"assets/medvezhonok/2025/10-11-29-3.webp","width":220,"height":271,"pixelWidth":220,"pixelHeight":271,"alt":"Футболка в бело-чёрную полоску","caption":"«Ювентус» · бьянконери"},{"src":"assets/medvezhonok/2025/10-11-29-4.webp","width":238,"height":270,"pixelWidth":238,"pixelHeight":270,"alt":"Футболка в бело-красную полоску","caption":"«Виченца» · ?"}]}}},{"author":"А. Пиперски","question":"В каком из этих падежей в окончаниях существительных не встречается буква ё?","choices":["в именительном","в родительном","в винительном","в творительном","в предложном."],"key":"Д","review":["Буква Ё в окончаниях","Проверь формы «ружьё» в именительном и винительном, «краёв» в родительном множественного и «ружьём» в творительном. Во всех этих окончаниях есть Ё.","В предложном падеже того же слова будет «о ружье». У других существительных возможны окончания «-е», «-и», «-у», «-ю», «-ах», «-ях», но ни в одном нет Ё."]}], {"year":2025,"grade":"10-11","tasksFile":"10-11.pdf","answersFile":"10-11-answers.pdf","sourceUrl":"https://konkurs43.ru/rm/task2025-1.zip"}), globalThis.KENGURU_CHOICE_LAYOUTS, {});
})({KenguruVisual: globalThis.KenguruVisual}, globalThis.KenguruEditions.register);
